using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1DeskApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_DeskPropRefinement/";static string O=>R+"/Docs/Review/2026-11-12_B1_DeskProps/";const string A="Assets/Afrer_Seconds/05.Model/Props/B1/";
 static Vector3 V(JToken q)=>new Vector3((float)q[0],(float)q[1],(float)q[2]);static float[] Arr(Vector3 v)=>new[]{v.x,v.y,v.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");return s;}
 static void Record(GameObject root){foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}}
 public static object Run(){var s=Check();Directory.CreateDirectory(O);var p=JObject.Parse(File.ReadAllText(H+"plan.json"));var models=JObject.Parse(File.ReadAllText(H+"models.json"));if(models.Count!=(int)p["variants"])throw new Exception("Model generation incomplete");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
  var ti=(TextureImporter)AssetImporter.GetAtPath(A+"Textures/DP_WorkRecords.png");ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.anisoLevel=4;ti.SaveAndReimport();
  string mp=A+"Materials/DP_WorkRecords.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="DP_WorkRecords"};AssetDatabase.CreateAsset(mat,mp);}mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Textures/DP_WorkRecords.png"));mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Smoothness",.16f);mat.SetFloat("_Metallic",0);EditorUtility.SetDirty(mat);
  string screenPath=A+"Materials/DP_WorkScreens.mat";var screen=AssetDatabase.LoadAssetAtPath<Material>(screenPath);if(!screen){screen=new Material(mat){name="DP_WorkScreens"};AssetDatabase.CreateAsset(screen,screenPath);}screen.SetTexture("_EmissionMap",mat.GetTexture("_BaseMap"));screen.SetColor("_EmissionColor",Color.white*.5f);screen.EnableKeyword("_EMISSION");screen.SetFloat("_Smoothness",.28f);EditorUtility.SetDirty(screen);
  foreach(var m in models){var importer=(ModelImporter)AssetImporter.GetAtPath((string)m.Value["asset"]);if(!importer)throw new Exception("Missing "+m.Key);importer.importAnimation=false;importer.animationType=ModelImporterAnimationType.None;importer.isReadable=false;importer.addCollider=false;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;
   foreach(var kv in (JObject)m.Value["materials"]){var material=AssetDatabase.LoadAssetAtPath<Material>((string)kv.Value);if(!material)throw new Exception("Missing material "+kv.Value);importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),material);}importer.SaveAndReimport();}
  var root=GameObject.Find("B1_ResearchAndStaffFloor");Undo.IncrementCurrentGroup();int ug=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Refine B1 desktop props");Undo.RegisterFullObjectHierarchyUndo(root,"B1 desktop refinement");int replaced=0;
  foreach(var q in p["targets"]){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);if(!t)throw new Exception("Missing placement "+q["name"]);var old=t.Find("DesktopRefinement");if(old)Undo.DestroyObjectImmediate(old.gameObject);
