   foreach(var rr in rs){rr.enabled=true;rr.shadowCastingMode=ShadowCastingMode.On;rr.receiveShadows=true;rr.lightProbeUsage=LightProbeUsage.BlendProbes;rr.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;GameObjectUtility.SetStaticEditorFlags(rr.gameObject,StaticEditorFlags.OccludeeStatic|StaticEditorFlags.ReflectionProbeStatic);}Record(go);replaced++;
  }
  foreach(var q in p["relocations"]){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);t.localPosition=V(q["position"]);t.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);}
  Record(root);Physics.SyncTransforms();Undo.CollapseUndoOperations(ug);EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);var result=new{replaced,variants=models.Count,relocatedRecorders=p["relocations"].Count(),saved=!s.isDirty};File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Audit(){var s=Check();var root=GameObject.Find("B1_ResearchAndStaffFloor");var b=JObject.Parse(File.ReadAllText(H+"before.json"));var plan=JObject.Parse(File.ReadAllText(H+"plan.json"));var errors=new List<string>();var moved=new HashSet<string>(plan["relocations"].Select(q=>(string)q["name"]));var all=root.GetComponentsInChildren<Transform>(true).GroupBy(P).ToDictionary(g=>g.Key,g=>g.ToList());int kept=0;
  foreach(var q in b["transforms"]){string path=(string)q["path"];if(moved.Any(n=>path.EndsWith("/"+n)))continue;if(!all.TryGetValue(path,out var list)){errors.Add("Missing "+path);continue;}var t=list.FirstOrDefault(v=>Vector3.Distance(v.localPosition,V(q["pos"]))<.0001f&&Vector3.Distance(v.localScale,V(q["scale"]))<.0001f&&Quaternion.Angle(v.localRotation,Quaternion.Euler(V(q["rot"])))<.015f&&v.gameObject.activeSelf==(bool)q["active"]);if(!t){errors.Add("Transform changed "+path);continue;}list.Remove(t);kept++;}
  var colliderPool=root.GetComponentsInChildren<Collider>(true).GroupBy(c=>P(c.transform)).ToDictionary(g=>g.Key,g=>g.ToList());int colliders=0;
  foreach(var q in b["colliders"]){string path=(string)q["path"];if(moved.Any(n=>path.EndsWith("/"+n)||path.Contains("/"+n+"/")))continue;if(!colliderPool.TryGetValue(path,out var cs)){errors.Add("Collider missing "+path);continue;}var match=cs.FirstOrDefault(c=>c.GetType().Name==(string)q["type"]&&c.enabled==(bool)q["enabled"]&&Vector3.Distance(c.bounds.center,V(q["center"]))<.001f&&Vector3.Distance(c.bounds.size,V(q["size"]))<.001f);if(!match)errors.Add("Collider changed "+path);else{cs.Remove(match);colliders++;}}
  foreach(var q in plan["targets"]){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);var visual=t.Find("DesktopRefinement");if(!visual){errors.Add("Missing variant "+t.name);continue;}var group=visual.GetComponent<LODGroup>();if(!group||group.GetLODs().Any(l=>l.renderers.Length!=1))errors.Add("Invalid LOD "+t.name);if(t.GetComponentsInChildren<Renderer>(true).Any(rr=>!rr.transform.IsChildOf(visual)&&rr.enabled))errors.Add("Old renderer remains "+t.name);}
  foreach(var f in root.GetComponentsInChildren<MeshFilter>(true))if(!f.sharedMesh)errors.Add("Missing mesh "+f.name);foreach(var rr in root.GetComponentsInChildren<Renderer>(true))if(rr.sharedMaterials.Any(m=>!m))errors.Add("Missing material "+rr.name);
  foreach(var q in b["lights"]){var g=GameObject.Find((string)q["path"]);var l=g?g.GetComponent<Light>():null;if(!l||l.enabled!=(bool)q["enabled"]||Mathf.Abs(l.intensity-(float)q["intensity"])>.001f||Mathf.Abs(l.range-(float)q["range"])>.001f)errors.Add("Light changed "+q["path"]);}
  var result=new{saved=!s.isDirty,targets=plan["targets"].Count(),protectedTransforms=kept,protectedColliders=colliders,errors,missingScripts=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),newReadableMeshes=root.GetComponentsInChildren<MeshFilter>().Count(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/DP_")&&f.sharedMesh.isReadable),activeLights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled),activeLodGroups=root.GetComponentsInChildren<LODGroup>().Count(g=>g.enabled)};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
